mapper.sql:
WHERE r.deleted = 0
  AND r.resource_status = 1

      AND r.publisher_id <> #{excludeUserId}


      AND NOT EXISTS (
          SELECT 1 FROM ai_user_behavior b
          WHERE b.user_id = #{excludeUserId}
            AND b.resource_id = r.id
            AND b.behavior_type = 1
      )

